Item.method_code:
const { rows, getState, itemTypeName, itemType } = options;
const state = getState();
const isMultiSelect = state.grid.selectedRows.length > 1;
if (isMultiSelect) {
	return {
		hidden: true
	};
}

const rowId = state.grid.selectedRows[0];
const lockedBy = rows.get(rowId, 'locked_by_id');
const isNewItem = ArasModules.item.isNew(itemTypeName, rowId);
const isVersionableIT = itemType['is_versionable'] === '1';
const isManualyVersionableIT = isVersionableIT && itemType['manual_versioning'] === '1';

const hidden =
	window.isFunctionDisabled(itemTypeName, 'Version') ||
	!isManualyVersionableIT ||
	isNewItem ||
	(lockedBy && lockedBy !== aras.user.id);
return { hidden };
